    dibuja($("#gVel"), k.vel, { x0: k.x0, x1: k.x1, xEt: k.xEt, yEt: "|q\u0307| (\xB0/s)", umbral: UMBRAL_ALARMA, cursor: cur });
    dibuja($("#gMarg"), k.marg, { x0: k.x0, x1: k.x1, xEt: k.xEt, yEt: "margen a los l\xEDmites (\xB0)", cero: true, cursor: cur, yMin: -10 });
